"""One-off: edits the proof/note templates of exec6 for the big plans of exec7 (register file of 2^KG + 8 words). Usage: python3 patch_docs.py KG KFMIN KFMAX"""
import sys
KG, KFMIN, KFMAX = [int(v) for v in sys.argv[1:4]]
RFW = (1 << KG) + 8
AMIN, AMAX = KG + KFMIN, KG + KFMAX


def sub(s, old, new, cnt=1):
    assert s.count(old) >= 1, old[:60]
    return s.replace(old, new) if cnt == 0 else s.replace(old, new, cnt)


p = open('proof_template_exec.md', newline='').read()
p = sub(p, "The wrapper (`pass_fwd`, `pass_inv`, `pass_fused`) charges the computation of the pass constants (a loop over the layers) and the `switch` on `k` (and on the mode) once per pass.",
        "The wrapper (`pass_fwd`, `pass_inv`, `pass_fused`) charges the computation of the pass constants (a loop over the layers) and the `switch` on `k` (and on the mode) once per pass. "
        "Big plans (`ntt_big.h`, generated by `gen_big.py %d %d %d`): a transform with %d <= a <= %d is run in two passes, a first pass of %d layers (blocks of 2^%d = %d data words, stride `s = 2^(a-%d)`) and a last pass of `a - %d` layers (blocks of stride 1, fused with the pointwise product); the planning test in `make_plan` is charged. "
        "The kernels of the big plans are the same straight-line text as above, written for %d layers (general kernel, and the `b = 0` kernel that omits the twiddle of `tp = 0` and its multiplication) and for %d to %d layers (`b = 0` kernel only, since the last pass has `s = 1`): every butterfly is the literal call `fp_bf` (one subtraction, one addition, one multiplication, in this order, exactly as the three statements of the small kernels), `fp_bfn` (subtraction and addition), `fp_ib` (multiplication, subtraction, addition) or `fp_ibn` (subtraction and addition), all defined in `pallas.c` by calls to `fp_sub`, `fp_add` and `fp_mul`, which count themselves; the twiddle statements and their charges are those of the small kernels, line by line. "
        "The load of the 2^k words of a block into the register file, their store, and the pointwise product are straight-line functions (`bgld`, `bgst`, `bgps`, `bgpm`), each word with its own `LD(1)` / `ST(1)` (and `LD(1)` for the second operand of the product). "
        "Each of these functions is called, not expanded, and its call and return are charged: `CTL(2)` for a load, store or pointwise call, `CTL(4)` for a kernel call, per block. In a big plan the group loop of the last pass has one block per group, and the first pass peels its block `b = 0` as the small passes do." % (KG, KFMIN, KFMAX, AMIN, AMAX, KG, KG, 1 << KG, KG, KG, KG, KFMIN, KFMAX))
old82 = p[p.index("* working registers (disclosed assumption):"):p.index("\n", p.index("* working registers (disclosed assumption):"))]
new82 = ("* working registers (declared assumption): the small kernels keep a block of 2^k <= 16 data words `x[]` in registers; the big plans keep a block of 2^%d = %d data words in a declared register file `RF` of %d words of 256 bits (%d data words and 8 working words: the twiddle operand, the butterfly temporary and the second operand of the pointwise product need three; five are spare). "
         "The register file is counted as memory: it is allocated once, by `ntt_init`, with `xalloc` (section 7), so it is inside the figure of the memory term (%d bytes of payload and a 64-byte header). The 18 words of the small kernels are ordinary locals of the pass functions, inside the stack bound of section 7. "
         "Strides, shift counts, base pointers and loop indices are held in integer registers (their updates are charged as control operations; they carry no memory-access charge). The 256-bit constants of the radix-3 kernels (`W3[1]`, `W3[2]`, `CH`, `DL`) are not assumed to be in registers: every use is charged as one load (`LD(1)` in the generated statement). The real cost of a machine with fewer registers would be higher; this is the one structural assumption of the model." % (KG, 1 << KG, RFW, 1 << KG, RFW * 32))
p = p.replace(old82, new82)
p = sub(p, "(i) the loops in the generated kernels (`ntt_kern.h`, `ntt_a3.h`, produced by `gen_kern.py`): the butterflies of a block and the radix-3 position kernels contain no loop at all, only the group loop and block loop around them, which are charged per iteration;",
        "(i) the loops in the generated kernels (`ntt_kern.h`, `ntt_big.h`, `ntt_a3.h`, produced by `gen_kern.py` and `gen_big.py`): the butterflies of a block, the loads, stores and pointwise products of a block and the radix-3 position kernels contain no loop at all (each is a literal statement, in `ntt_big.h` through the macros `bgB`, `bgLX8` and the like, which the preprocessor expands to literal statements), only the group loop and block loop around them, which are charged per iteration;")
p = sub(p, "run as passes of at most four layers (blocks of at most 16 data words in registers; with the two working words the register file is 18 words of 256 bits, see section 4.2).",
        "run as passes of at most four layers (blocks of at most 16 data words in registers), or, for %d <= a <= %d, as two passes of %d and a - %d layers (blocks of up to %d data words in the declared register file of %d words, see section 4.2)." % (AMIN, AMAX, KG, KG, 1 << KG, RFW))
if "It consists of the code, tables and static state" in p:
    p = sub(p, "It consists of the code, tables and static state of the shipped source only (the transform kernels are most of it).",
            "It consists of the code, tables and static state of the shipped source only (the transform kernels are most of it). The declared register file of %d words is not in the bss: it is one block of the arena (section 4.2), so it is counted in the heap figures below." % RFW)
else:
    p = sub(p, "(b) The footprint of the allocator at its peak.", "(b) The declared register file of %d words (section 4.2) is one allocation of `ntt_init`, made with `xalloc` like every buffer: it is inside the footprint of the allocator at its peak, not in the image. The footprint of the allocator at its peak." % RFW)
open('proof_template_exec.md', 'w', newline='').write(p)

n = open('note_template.md', newline='').read()
n = sub(n, "a register file of 18 words of 256 bits per transform block (16 data words and two working words: the twiddle operand and the butterfly temporary).",
        "a declared register file: 18 words of 256 bits per block for the small transforms, and %d words (%d data words of one block and 8 working words) for the transforms of 2^%d to 2^%d points, which run in two passes; that file is allocated from the counted arena and is part of the memory figure." % (RFW, 1 << KG, AMIN, AMAX))
n = sub(n, "and the generated transform kernels, whose butterflies and radix-3 position kernels are straight-line code.",
        "and the generated transform kernels (ntt_kern.h, ntt_big.h, ntt_a3.h), whose butterflies, loads, stores and radix-3 position kernels are straight-line code.")
open('note_template.md', 'w', newline='').write(n)

t = open('note_tail.py', newline='').read()
t = sub(t, "with the register file of 18 words of 256 bits (16 data words and two working words).",
        "with the declared register file (18 words per block for the small transforms; %d words, %d of them data, for the two-pass transforms, allocated from the counted arena)." % (RFW, 1 << KG))
t = sub(t, "a register file of 18 words of 256 bits per transform block (16 data words and two working words: the twiddle operand and the butterfly temporary);",
        "a declared register file of 18 words per transform block (small transforms) and of %d words (%d data words and 8 working words) for the transforms of 2^%d to 2^%d points, which is counted as memory;" % (RFW, 1 << KG, AMIN, AMAX))
open('note_tail.py', 'w', newline='').write(t)

b = open('build_package.py', newline='').read()
b = sub(b, "'gen_kern.py', 'ntt_kern.h', 'ntt_a3.h',", "'gen_kern.py', 'gen_big.py', 'ntt_kern.h', 'ntt_big.h', 'ntt_a3.h',")
open('build_package.py', 'w', newline='').write(b)
print('patched')
